const root = resolve(process.argv[3] ?? '/tmp/charming-app-build');
const controller = new AbortController();
const onDisconnect = () => {
  controller.abort();
  setTimeout(() => {
    rmSync(root, { recursive: true, force: true });
    try {
      process.kill(-process.pid, 'SIGKILL');
    } catch {
      process.exit(1);
    }
  }, 500);
};
